    'This bulk action applies only to messages visible on this page. The server re-checks access for every selected message before deletion.' => 'Diese Massenaktion gilt nur für auf dieser Seite sichtbare Nachrichten. Der Server prüft den Zugriff für jede ausgewählte Nachricht vor dem Löschen erneut.',
